<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Services\StudentAttendance;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use Carbon\CarbonImmutable;
class AttendanceController extends Controller
{
 public function __construct(private StudentAttendance $attendance){}
 public function setup(Request $r){[$sid,$campuses,$m]=$this->attendance->context($r);return response()->json(['today'=>$this->attendance->today(),'can_manage'=>$this->attendance->access->can($r,'attendance.manage'),'can_correct'=>$this->attendance->access->can($r,'attendance.correct'),'oversee'=>$this->attendance->access->can($r,'attendance.oversee'),'sections'=>$this->attendance->sections($r,$sid,$campuses,$m)->orderByDesc('y.starts_on')->orderBy('c.position')->orderBy('s.name')->get()]);}
 public function day(Request $r){$d=$r->validate(['section_id'=>'required|integer','date'=>'required|date_format:Y-m-d']);return DB::transaction(fn()=>response()->json($this->attendance->day($r,$d['section_id'],$d['date'])));}
 public function save(Request $r){$this->attendance->context($r,true);$d=$r->validate(['section_id'=>'required|integer','date'=>'required|date_format:Y-m-d','revision'=>'required|integer|min:0','action'=>['required',Rule::in(['draft','submit','day_off'])],'reason'=>'nullable|string|min:5|max:1000','records'=>'present|array|max:1000','records.*.enrollment_id'=>'required|integer|distinct','records.*.status'=>['nullable',Rule::in(['present','absent','late','leave'])],'records.*.remarks'=>'nullable|string|max:500']);return response()->json($this->attendance->save($r,$d));}
 public function overview(Request $r){return DB::transaction(fn()=>$this->overviewData($r));}
 private function overviewData(Request $r){[$sid,$campuses,$m]=$this->attendance->context($r);$d=$r->validate(['date'=>'required|date_format:Y-m-d|before_or_equal:'.$this->attendance->today()]);$sections=$this->attendance->sections($r,$sid,$campuses,$m)->where('y.starts_on','<=',$d['date'])->where('y.ends_on','>=',$d['date'])->orderBy('p.name')->orderBy('c.position')->get();$sessions=DB::table('attendance_sessions')->where('school_id',$sid)->whereIn('section_id',$sections->pluck('id'))->where('attendance_date',$d['date'])->get()->keyBy('section_id');$counts=DB::table('attendance_records')->where('school_id',$sid)->whereIn('attendance_session_id',$sessions->pluck('id'))->selectRaw('attendance_session_id,status,COUNT(*) AS n')->groupBy('attendance_session_id','status')->get()->groupBy('attendance_session_id');$eligible=DB::table('enrollments')->where('school_id',$sid)->whereIn('section_id',$sections->pluck('id'))->where('starts_on','<=',$d['date'])->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$d['date']))->selectRaw('section_id,COUNT(*) AS n')->groupBy('section_id')->pluck('n','section_id');
  foreach($sections as $section){$day=$sessions->get($section->id);$section->attendance_status=$day?->status??'not_started';$section->revision=(int)($day->revision??0);$section->eligible=(int)($eligible[$section->id]??0);$section->counts=['present'=>0,'absent'=>0,'late'=>0,'leave'=>0];foreach($counts->get($day?->id)??[] as $count)$section->counts[$count->status]=(int)$count->n;$section->marked=array_sum($section->counts);$section->unmarked=$section->attendance_status==='non_instructional'?0:max(0,$section->eligible-$section->marked);$section->day_note=$day?->day_note;}
  return response()->json(['date'=>$d['date'],'sections'=>$sections]);
 }
 public function history(Request $r){$d=$r->validate(['section_id'=>'required|integer','date'=>'required|date_format:Y-m-d','page'=>'nullable|integer|min:1']);[$sid,$section]=$this->attendance->section($r,$d['section_id']);$this->attendance->date($section,$d['date']);$session=DB::table('attendance_sessions')->where('school_id',$sid)->where('section_id',$section->id)->where('attendance_date',$d['date'])->first();$rows=DB::table('audit_logs as a')->leftJoin('school_memberships as m','m.id','=','a.actor_membership_id')->leftJoin('users as u','u.id','=','m.user_id')->where('a.school_id',$sid)->where('a.target_type','attendance_sessions')->where('a.target_id',$session?->id??0)->where('a.action','like','attendance.%')->orderByDesc('a.id')->paginate(10,['a.id','a.action','a.changes','a.occurred_at','u.name as actor_name']);foreach($rows as $row){$row->changes=json_decode($row->changes??'{}',true);$row->occurred_at=CarbonImmutable::parse($row->occurred_at,'UTC')->setTimezone('Asia/Karachi')->format('Y-m-d H:i:s');}return response()->json($rows);}
 public function report(Request $r){$d=$r->validate(['section_id'=>'required|integer','month'=>'required|date_format:Y-m']);return DB::transaction(function()use($r,$d){[$sid,$section]=$this->attendance->section($r,$d['section_id']);$start=CarbonImmutable::createFromFormat('!Y-m',$d['month'],'Asia/Karachi');$end=$start->endOfMonth();$first=max($start->toDateString(),$section->session_start);$last=min($end->toDateString(),$section->session_end,$this->attendance->today());if($first>$last)$this->attendance->fail('Choose a month inside the academic session and through today.');$sessions=DB::table('attendance_sessions')->where('school_id',$sid)->where('section_id',$section->id)->whereBetween('attendance_date',[$first,$last])->get()->keyBy('attendance_date');$records=DB::table('attendance_records')->where('school_id',$sid)->whereIn('attendance_session_id',$sessions->pluck('id'))->get()->groupBy('attendance_session_id');
   $enrollments=DB::table('enrollments as e')->join('students as s','s.id','=','e.student_id')->where('e.school_id',$sid)->where('e.section_id',$section->id)->where(function($q)use($first,$last,$records){$q->where(function($q)use($first,$last){$q->where('e.starts_on','<=',$last)->where(fn($q)=>$q->whereNull('e.ends_on')->orWhere('e.ends_on','>=',$first));})->orWhereIn('e.id',$records->flatten(1)->pluck('enrollment_id'));})->orderBy('e.roll_no')->orderBy('s.first_name')->get(['e.id','e.student_id','e.starts_on','e.ends_on','e.roll_no','s.first_name','s.last_name','s.admission_no']);$map=[];foreach($sessions as $day)$map[$day->attendance_date]=($records->get($day->id)??collect())->keyBy('enrollment_id');$dates=[];$summary=['submitted'=>0,'draft'=>0,'non_instructional'=>0,'not_started'=>0,'no_roster'=>0];
   for($date=CarbonImmutable::parse($first);$date->toDateString()<=$last;$date=$date->addDay()){$key=$date->toDateString();$session=$sessions->get($key);$eligible=$enrollments->filter(fn($e)=>$e->starts_on<=$key&&($e->ends_on===null||$e->ends_on>=$key))->count();$status=$session?->status??($eligible?'not_started':'no_roster');if(isset($summary[$status]))$summary[$status]++;$dates[]=['date'=>$key,'state'=>$status,'eligible'=>$eligible,'day_note'=>$session?->day_note];}
   $rows=[];$warnings=$records->flatten(1)->whereNotIn('enrollment_id',$enrollments->pluck('id'))->count();foreach($enrollments as $student){$counts=['present'=>0,'absent'=>0,'late'=>0,'leave'=>0,'unmarked'=>0,'draft'=>0,'non_instructional'=>0];$cells=[];foreach($dates as $day){$date=$day['date'];$eligible=$student->starts_on<=$date&&($student->ends_on===null||$student->ends_on>=$date);$record=isset($map[$date])?$map[$date]->get($student->id):null;$warning=$record&&!$eligible;if($warning)$warnings++;$state='not_enrolled';if($eligible||$record){if($day['state']==='non_instructional'){$state='non_instructional';$counts['non_instructional']++;}elseif($day['state']==='submitted'&&$record){$state=$record->status;$counts[$state]++;}elseif($day['state']==='draft'){$state='draft';$counts['draft']++;}else{$state='unmarked';$counts['unmarked']++;}}$cells[]=['date'=>$date,'state'=>$state,'draft_status'=>$day['state']==='draft'?$record?->status:null,'remarks'=>$record?->remarks,'roster_warning'=>(bool)$warning];}$marked=$counts['present']+$counts['absent']+$counts['late']+$counts['leave'];$rows[]=get_object_vars($student)+['cells'=>$cells,'counts'=>$counts,'marked_days'=>$marked,'attendance_percent'=>$marked?round(100*($counts['present']+$counts['late'])/$marked,2):null];}
   return response()->json(['section'=>$section,'month'=>$d['month'],'through'=>$last,'dates'=>$dates,'summary'=>$summary,'rows'=>$rows,'roster_warnings'=>$warnings,'formula'=>'Attendance % = (Present + Late) / submitted marked days. Leave counts as a marked day. Drafts, unsubmitted days and non-instructional days are excluded. No weekend is automatically assumed.']);});}
}
